<script>
  export let data = [];
  export let columns = [];

  let sortColumn = null;
  let sortDirection = 'asc';
  let filters = {};
  let selectedRows = new Set();
  let selectAll = false;

  // Filtered and sorted data
  $: filteredData = applyFilters(data, filters);
  $: sortedData = applySort(filteredData, sortColumn, sortDirection);

  function applyFilters(items, filterObj) {
    return items.filter(item => {
      return Object.entries(filterObj).every(([key, value]) => {
        if (!value || value === '') return true;
        const itemValue = String(item[key] || '').toLowerCase();
        return itemValue.includes(value.toLowerCase());
      });
    });
  }

  function applySort(items, column, direction) {
    if (!column) return items;
    
    return [...items].sort((a, b) => {
      let aVal = a[column];
      let bVal = b[column];

      // Handle numbers
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return direction === 'asc' ? aVal - bVal : bVal - aVal;
      }

      // Handle strings
      aVal = String(aVal || '').toLowerCase();
      bVal = String(bVal || '').toLowerCase();

      if (direction === 'asc') {
        return aVal.localeCompare(bVal);
      } else {
        return bVal.localeCompare(aVal);
      }
    });
  }

  function handleSort(column) {
    if (!columns.find(c => c.key === column)?.sortable) return;

    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }
  }

  function handleFilter(column, value) {
    filters = { ...filters, [column]: value };
  }

  function clearFilters() {
    filters = {};
  }

  function toggleSelectAll() {
    if (selectAll) {
      selectedRows = new Set();
    } else {
      selectedRows = new Set(sortedData.map(item => item.$id || item.id));
    }
    selectAll = !selectAll;
  }

  function toggleRowSelect(id) {
    if (selectedRows.has(id)) {
      selectedRows.delete(id);
    } else {
      selectedRows.add(id);
    }
    selectedRows = selectedRows;
    selectAll = selectedRows.size === sortedData.length;
  }

  function formatValue(value, column) {
    if (value === null || value === undefined) return '--';
    
    if (column.type === 'date' && value) {
      return new Date(value).toLocaleDateString('zh-CN');
    }
    
    if (column.type === 'number') {
      return Number(value).toLocaleString();
    }

    return String(value);
  }
</script>

<div class="data-table-container">
  {#if Object.keys(filters).some(k => filters[k])}
    <div class="filter-bar">
      <span>已应用筛选条件</span>
      <button class="clear-filters-btn" on:click={clearFilters}>清除全部</button>
    </div>
  {/if}

  <div class="table-wrapper">
    <table class="data-table">
      <thead>
        <tr class="header-row">
          <th class="checkbox-cell">
            <input 
              type="checkbox" 
              checked={selectAll}
              on:change={toggleSelectAll}
            />
          </th>
          <th class="index-cell">#</th>
          {#each columns as column}
            <th 
              class:sortable={column.sortable}
              class:sorted={sortColumn === column.key}
              on:click={() => handleSort(column.key)}
            >
              <div class="th-content">
                <span>{column.label}</span>
                {#if column.sortable}
                  <span class="sort-icon">
                    {#if sortColumn === column.key}
                      {sortDirection === 'asc' ? '↑' : '↓'}
                    {:else}
                      ↕
                    {/if}
                  </span>
                {/if}
              </div>
            </th>
          {/each}
        </tr>
        <tr class="filter-row">
          <th></th>
          <th></th>
          {#each columns as column}
            <th>
              {#if column.filterable}
                <input 
                  type="text" 
                  class="filter-input"
                  placeholder="筛选..."
                  value={filters[column.key] || ''}
                  on:input={(e) => handleFilter(column.key, e.target.value)}
                />
              {/if}
            </th>
          {/each}
        </tr>
      </thead>
      <tbody>
        {#each sortedData as row, index (row.$id || row.id || index)}
          <tr class:selected={selectedRows.has(row.$id || row.id)}>
            <td class="checkbox-cell">
              <input 
                type="checkbox" 
                checked={selectedRows.has(row.$id || row.id)}
                on:change={() => toggleRowSelect(row.$id || row.id)}
              />
            </td>
            <td class="index-cell">{index + 1}</td>
            {#each columns as column}
              <td 
                class:highlight={column.highlight}
                class:number-cell={column.type === 'number'}
              >
                {formatValue(row[column.key], column)}
              </td>
            {/each}
          </tr>
        {:else}
          <tr>
            <td colspan={columns.length + 2} class="empty-cell">
              暂无数据
            </td>
          </tr>
        {/each}
      </tbody>
    </table>
  </div>

  <div class="table-footer">
    <span class="row-count">
      共 {sortedData.length} 条记录
      {#if selectedRows.size > 0}
        ，已选择 {selectedRows.size} 条
      {/if}
    </span>
  </div>
</div>

