<script>
  import { auth, AUTH_ERRORS } from './providers/index.js'
  import { 
    verifySuperAdminCredentials, 
    checkSuperAdminExists, 
    initializeSuperAdmin,
    loginSuperAdmin 
  } from './services/superAdmin.js'

  export let onLoginSuccess = () => {}

  let username = ''
  let password = ''
  let isLoading = false
  let errorMessage = ''
  let isRegistering = false
  let initializingMessage = ''

  async function handleAuth() {
    if (!username.trim() || !password.trim()) {
      errorMessage = '请输入用户名和密码'
      return
    }

    isLoading = true
    errorMessage = ''
    initializingMessage = ''

    try {
      // Check if this is super admin credentials
      if (!isRegistering && verifySuperAdminCredentials(username, password)) {
        await handleSuperAdminLogin()
        return
      }

      if (isRegistering) {
        // 注册逻辑
        const { data, error } = await auth.signUp(
          `${username}@example.com`,
          password,
          { username }
        )

        if (error) {
          throw error
        }

        // 注册成功后自动登录
        if (data.user) {
          await signIn()
        }
      } else {
        // 登录逻辑
        await signIn()
      }
    } catch (error) {
      console.error('认证错误:', error)
      
      if (error.message === AUTH_ERRORS.INVALID_CREDENTIALS) {
        errorMessage = '用户名或密码错误'
      } else if (error.message && error.message.includes('User already registered')) {
        errorMessage = '用户名已被注册'
      } else {
        errorMessage = error.message || '登录失败，请重试'
      }
    } finally {
      isLoading = false
      initializingMessage = ''
    }
  }

  async function handleSuperAdminLogin() {
    try {
      // Check if super admin account exists in Appwrite
      initializingMessage = '检查超级管理员账户...'
      const exists = await checkSuperAdminExists()

      if (!exists) {
        // Create super admin account
        initializingMessage = '首次登录，正在初始化超级管理员账户...'
        const result = await initializeSuperAdmin()
        
        if (!result.success) {
          throw new Error('Failed to initialize super admin')
        }
        
        initializingMessage = '初始化完成，正在登录...'
      }

      // Login with Appwrite auth
      const loginResult = await loginSuperAdmin()
      
      if (loginResult.success) {
        // Ensure user profile exists
        await auth.ensureUserProfile(loginResult.user, username)
        onLoginSuccess(loginResult.user, true)
      }
    } catch (error) {
      console.error('Super admin login error:', error)
      errorMessage = '超级管理员登录失败: ' + (error.message || '未知错误')
      throw error
    }
  }

  async function signIn() {
    const { data, error } = await auth.signIn(
      `${username}@example.com`,
      password
    )

    if (error) {
      throw error
    }

    if (data.user) {
      // 确保用户资料存在
      await auth.ensureUserProfile(data.user, username)
      onLoginSuccess(data.user, false)
    }
  }

  function handleKeyPress(event) {
    if (event.key === 'Enter') {
      handleAuth()
    }
  }

  function toggleMode() {
    isRegistering = !isRegistering
    errorMessage = ''
  }
</script>

<div class="login-container">
  <div class="login-card">
    <div class="login-header">
      <h1>{isRegistering ? '注册账户' : '欢迎登录'}</h1>
      <p class="subtitle">{isRegistering ? '创建新的账户' : '建筑材料管理系统'}</p>
    </div>

    <form class="login-form" on:submit|preventDefault={handleAuth}>
      <div class="form-group">
        <label for="username">用户名</label>
        <input
          id="username"
          type="text"
          bind:value={username}
          placeholder="请输入用户名"
          on:keypress={handleKeyPress}
          disabled={isLoading}
          required
        />
      </div>

      <div class="form-group">
        <label for="password">密码</label>
        <input
          id="password"
          type="password"
          bind:value={password}
          placeholder="请输入密码"
          on:keypress={handleKeyPress}
          disabled={isLoading}
          required
        />
      </div>

      {#if errorMessage}
        <div class="error-message">
          {errorMessage}
        </div>
      {/if}

      {#if initializingMessage}
        <div class="info-message">
          <div class="spinner-small"></div>
          {initializingMessage}
        </div>
      {/if}

      <button 
        type="submit" 
        class="login-button"
        disabled={isLoading}
      >
        {#if isLoading}
          <span class="spinner"></span>
          {isRegistering ? '注册中...' : '登录中...'}
        {:else}
          {isRegistering ? '注册' : '登录'}
        {/if}
      </button>
    </form>
  </div>
</div>

