// BMMS Database Service
// Provides high-level API for BMMS operations on top of Appwrite

import { db } from '../providers/index.js';

// Collection names (must match Appwrite database schema)
export const COLLECTIONS = {
    PROJECTS: 'projects',
    CATEGORIES: 'categories',
    MATERIALS: 'materials',
    INBOUND_RECORDS: 'inbound_records',
    OUTBOUND_RECORDS: 'outbound_records',
    USERS: 'users'
};

// =============================================
// Projects API
// =============================================
export const projectsApi = {
    async list() {
        const result = await db.from(COLLECTIONS.PROJECTS).select('*').order('created_at', { ascending: false }).exec();
        return result;
    },

    async create(name, description = '', createdBy) {
        const data = {
            name,
            description,
            created_by: createdBy
        };
        return await db.from(COLLECTIONS.PROJECTS).insert(data);
    },

    async update(projectId, data) {
        return await db.from(COLLECTIONS.PROJECTS).update(data).eq('$id', projectId);
    },

    async delete(projectId) {
        // First delete all related categories, materials, and records
        await categoriesApi.deleteByProject(projectId);
        return await db.from(COLLECTIONS.PROJECTS).eq('$id', projectId).delete();
    }
};

// =============================================
// Categories API (Level 3 - e.g., "Pipes", "Valves")
// =============================================
export const categoriesApi = {
    async listByProject(projectId) {
        const result = await db.from(COLLECTIONS.CATEGORIES)
            .select('*')
            .eq('project_id', projectId)
            .order('sort_order', { ascending: true })
            .exec();
        return result;
    },

    async create(projectId, name, sortOrder = 0) {
        const data = {
            project_id: projectId,
            name,
            sort_order: sortOrder
        };
        return await db.from(COLLECTIONS.CATEGORIES).insert(data);
    },

    async update(categoryId, data) {
        return await db.from(COLLECTIONS.CATEGORIES).update(data).eq('$id', categoryId);
    },

    async delete(categoryId) {
        // Delete all materials and records in this category first
        await materialsApi.deleteByCategory(categoryId);
        return await db.from(COLLECTIONS.CATEGORIES).eq('$id', categoryId).delete();
    },

    async deleteByProject(projectId) {
        const categories = await this.listByProject(projectId);
        if (categories.data) {
            for (const cat of categories.data) {
                await this.delete(cat.$id);
            }
        }
    }
};

// =============================================
// Materials API (Aggregate/Snapshot)
// =============================================
export const materialsApi = {
    async listByCategory(categoryId) {
        const result = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('category_id', categoryId)
            .order('name', { ascending: true })
            .exec();
        return result;
    },

    async listByProject(projectId) {
        const result = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('project_id', projectId)
            .order('name', { ascending: true })
            .exec();
        return result;
    },

    /**
     * Find existing material or create new one
     * Exact match required: name + specification + material_type
     */
    async findOrCreate(projectId, categoryId, materialData) {
        // Validate required fields
        if (!materialData.name || !materialData.specification || !materialData.material_type) {
            return {
                data: null,
                error: new Error('名称、规格型号和材质为必填项')
            };
        }

        // Try to find exact match by name + specification + material_type
        const findResult = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('project_id', projectId)
            .eq('category_id', categoryId)
            .eq('name', materialData.name)
            .eq('specification', materialData.specification)
            .eq('material_type', materialData.material_type)
            .single();

        if (findResult.data) {
            // Found existing material
            return { ...findResult, created: false };
        }

        // Not found, create new material
        const newMaterial = {
            project_id: projectId,
            category_id: categoryId,
            name: materialData.name,
            specification: materialData.specification,
            material_type: materialData.material_type,
            description: materialData.description || '',
            unit: materialData.unit,
            total_inbound: 0,
            total_outbound: 0,
            remaining_qty: 0
        };

        const result = await db.from(COLLECTIONS.MATERIALS).insert(newMaterial);
        return { ...result, created: true };
    },

    async updateTotals(materialId) {
        // Recalculate totals from records
        const inboundResult = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .select('quantity')
            .eq('material_id', materialId)
            .exec();

        const outboundResult = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .select('quantity')
            .eq('material_id', materialId)
            .exec();

        const totalInbound = (inboundResult.data || []).reduce((sum, r) => sum + (r.quantity || 0), 0);
        const totalOutbound = (outboundResult.data || []).reduce((sum, r) => sum + (r.quantity || 0), 0);
        const remainingQty = totalInbound - totalOutbound;

        return await db.from(COLLECTIONS.MATERIALS).update({
            total_inbound: totalInbound,
            total_outbound: totalOutbound,
            remaining_qty: remainingQty
        }).eq('$id', materialId);
    },

    async deleteByCategory(categoryId) {
        // Delete all inbound/outbound records first
        const materials = await this.listByCategory(categoryId);
        if (materials.data) {
            for (const mat of materials.data) {
                await inboundRecordsApi.deleteByMaterial(mat.$id);
                await outboundRecordsApi.deleteByMaterial(mat.$id);
            }
        }
        return await db.from(COLLECTIONS.MATERIALS).eq('category_id', categoryId).delete();
    }
};

// =============================================
// Inbound Records API
// =============================================
export const inboundRecordsApi = {
    async listByCategory(categoryId) {
        // Get all inbound records for this category
        const result = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .select('*')
            .eq('category_id', categoryId)
            .order('arrival_date', { ascending: false })
            .exec();

        if (!result.data || result.data.length === 0) {
            return result;
        }

        // Fetch material details for each record
        const recordsWithMaterials = await Promise.all(
            result.data.map(async (record) => {
                const materialResult = await db.from(COLLECTIONS.MATERIALS)
                    .select('*')
                    .eq('$id', record.material_id)
                    .single();

                const material = materialResult.data || {};

                // Merge record with material data
                return {
                    ...record,
                    name: material.name || '',
                    specification: material.specification || '',
                    material_type: material.material_type || '',
                    description: material.description || '',
                    unit: material.unit || ''
                };
            })
        );

        return { data: recordsWithMaterials, error: null };
    },

    async listByMaterial(materialId) {
        const result = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .select('*')
            .eq('material_id', materialId)
            .order('arrival_date', { ascending: false })
            .exec();
        return result;
    },

    async create(projectId, categoryId, materialId, data) {
        const record = {
            project_id: projectId,
            category_id: categoryId,
            material_id: materialId,
            quantity: data.quantity,
            arrival_date: data.arrival_date,
            batch_no: data.batch_no || '',
            remarks: data.remarks || ''
        };

        const result = await db.from(COLLECTIONS.INBOUND_RECORDS).insert(record);

        // Update material totals
        if (result.data) {
            await materialsApi.updateTotals(materialId);
        }

        return result;
    },

    async delete(recordId, materialId) {
        const result = await db.from(COLLECTIONS.INBOUND_RECORDS).eq('$id', recordId).delete();
        // Recalculate totals
        await materialsApi.updateTotals(materialId);
        return result;
    },

    async deleteByMaterial(materialId) {
        return await db.from(COLLECTIONS.INBOUND_RECORDS).eq('material_id', materialId).delete();
    }
};

// =============================================
// Outbound Records API
// =============================================
export const outboundRecordsApi = {
    async listByCategory(categoryId) {
        // Get all outbound records for this category
        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .select('*')
            .eq('category_id', categoryId)
            .order('outbound_date', { ascending: false })
            .exec();

        if (!result.data || result.data.length === 0) {
            return result;
        }

        // Fetch material details for each record
        const recordsWithMaterials = await Promise.all(
            result.data.map(async (record) => {
                const materialResult = await db.from(COLLECTIONS.MATERIALS)
                    .select('*')
                    .eq('$id', record.material_id)
                    .single();

                const material = materialResult.data || {};

                // Merge record with material data
                return {
                    ...record,
                    name: material.name || '',
                    specification: material.specification || '',
                    material_type: material.material_type || '',
                    description: material.description || '',
                    unit: material.unit || ''
                };
            })
        );

        return { data: recordsWithMaterials, error: null };
    },

    async listByMaterial(materialId) {
        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .select('*')
            .eq('material_id', materialId)
            .order('outbound_date', { ascending: false })
            .exec();
        return result;
    },

    /**
     * Create outbound record with stock validation
     */
    async create(projectId, categoryId, materialId, data) {
        // First, check remaining stock
        const material = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('$id', materialId)
            .single();

        if (!material.data) {
            return { data: null, error: new Error('Material not found') };
        }

        const remainingQty = material.data.remaining_qty || 0;
        if (data.quantity > remainingQty) {
            return {
                data: null,
                error: new Error(`库存不足！剩余: ${remainingQty}, 请求: ${data.quantity}`)
            };
        }

        const record = {
            project_id: projectId,
            category_id: categoryId,
            material_id: materialId,
            quantity: data.quantity,
            outbound_date: data.outbound_date,
            outbound_no: data.outbound_no || '',
            remarks: data.remarks || ''
        };

        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS).insert(record);

        // Update material totals
        if (result.data) {
            await materialsApi.updateTotals(materialId);
        }

        return result;
    },

    async delete(recordId, materialId) {
        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS).eq('$id', recordId).delete();
        // Recalculate totals
        await materialsApi.updateTotals(materialId);
        return result;
    },

    async deleteByMaterial(materialId) {
        return await db.from(COLLECTIONS.OUTBOUND_RECORDS).eq('material_id', materialId).delete();
    }
};

// =============================================
// Users API (for admin management)
// =============================================
export const usersApi = {
    async list() {
        const result = await db.from(COLLECTIONS.USERS)
            .select('*')
            .order('created_at', { ascending: false })
            .exec();
        return result;
    },

    async create(email, username, password, role = 'operator') {
        // Import auth and db from providers
        const { auth, db } = await import('../providers/index.js');
        const { config } = await import('../config.js');

        try {
            // Create Appwrite auth user
            const { data: authData, error: authError } = await auth.signUp(
                email,
                password,
                { username }
            );

            if (authError) {
                return { data: null, error: authError };
            }

            // Create user profile in users collection
            // IMPORTANT: Use the same ID as the auth user
            const userId = authData.user.$id || authData.user.id;

            // Get direct access to Appwrite databases
            const databases = db.getDatabase();
            const databaseId = config.APPWRITE_DATABASE_ID || 'bmms';

            try {
                // Create document with specific ID (same as auth user ID)
                const userDoc = await databases.createDocument(
                    databaseId,
                    COLLECTIONS.USERS,
                    userId,  // Use auth user ID as document ID
                    {
                        email,
                        username,
                        role
                    }
                );

                return { data: userDoc, error: null };
            } catch (dbError) {
                console.error('Failed to create user profile:', dbError);
                // Return error but indicate auth user was created
                return {
                    data: null,
                    error: new Error(`User auth created but profile failed: ${dbError.message}`)
                };
            }
        } catch (error) {
            console.error('Create user error:', error);
            return { data: null, error };
        }
    },

    async updateRole(userId, role) {
        return await db.from(COLLECTIONS.USERS).update({ role }).eq('$id', userId);
    },

    async delete(userId) {
        // Note: This only deletes the user profile, not the Appwrite auth user
        // Deleting auth users requires admin SDK which isn't available in browser
        return await db.from(COLLECTIONS.USERS).eq('$id', userId).delete();
    }
};

