// Svelte stores for application state
import { writable, derived } from 'svelte/store';

// =============================================
// Auth Store
// =============================================
function createAuthStore() {
    const { subscribe, set, update } = writable({
        user: null,
        role: null, // 'super_admin', 'admin', 'operator'
        isLoading: true,
        isSuperAdmin: false
    });

    return {
        subscribe,
        setUser: (user, role = 'operator', isSuperAdmin = false) => {
            set({ user, role, isLoading: false, isSuperAdmin });
        },
        clearUser: () => {
            set({ user: null, role: null, isLoading: false, isSuperAdmin: false });
        },
        setLoading: (isLoading) => {
            update(state => ({ ...state, isLoading }));
        }
    };
}

export const authStore = createAuthStore();

// =============================================
// Project Store (Sidebar Tree Data)
// =============================================
function createProjectStore() {
    const { subscribe, set, update } = writable({
        projects: [],
        selectedProjectId: null,
        selectedCategoryId: null,
        selectedViewType: null, // 'inbound', 'outbound', 'remaining'
        isLoading: false
    });

    return {
        subscribe,
        setProjects: (projects) => {
            update(state => ({ ...state, projects, isLoading: false }));
        },
        selectProject: (projectId) => {
            update(state => ({ ...state, selectedProjectId: projectId, selectedCategoryId: null, selectedViewType: null }));
        },
        selectView: (projectId, viewType, categoryId = null) => {
            update(state => ({
                ...state,
                selectedProjectId: projectId,
                selectedViewType: viewType,
                selectedCategoryId: categoryId
            }));
        },
        setLoading: (isLoading) => {
            update(state => ({ ...state, isLoading }));
        },
        addProject: (project) => {
            update(state => ({ ...state, projects: [...state.projects, project] }));
        },
        removeProject: (projectId) => {
            update(state => ({
                ...state,
                projects: state.projects.filter(p => p.$id !== projectId),
                selectedProjectId: state.selectedProjectId === projectId ? null : state.selectedProjectId
            }));
        }
    };
}

export const projectStore = createProjectStore();

// =============================================
// Material Store (Current View Data)
// =============================================
function createMaterialStore() {
    const { subscribe, set, update } = writable({
        materials: [],
        categories: [],
        inboundRecords: [],
        outboundRecords: [],
        isLoading: false,
        filters: {},
        sortColumn: null,
        sortDirection: 'asc'
    });

    return {
        subscribe,
        setMaterials: (materials) => {
            update(state => ({ ...state, materials, isLoading: false }));
        },
        setCategories: (categories) => {
            update(state => ({ ...state, categories }));
        },
        setInboundRecords: (records) => {
            update(state => ({ ...state, inboundRecords: records, isLoading: false }));
        },
        setOutboundRecords: (records) => {
            update(state => ({ ...state, outboundRecords: records, isLoading: false }));
        },
        setLoading: (isLoading) => {
            update(state => ({ ...state, isLoading }));
        },
        setFilter: (column, value) => {
            update(state => ({
                ...state,
                filters: { ...state.filters, [column]: value }
            }));
        },
        clearFilters: () => {
            update(state => ({ ...state, filters: {} }));
        },
        setSort: (column, direction) => {
            update(state => ({ ...state, sortColumn: column, sortDirection: direction }));
        },
        reset: () => {
            set({
                materials: [],
                categories: [],
                inboundRecords: [],
                outboundRecords: [],
                isLoading: false,
                filters: {},
                sortColumn: null,
                sortDirection: 'asc'
            });
        }
    };
}

export const materialStore = createMaterialStore();

// =============================================
// UI Store (Modals, Notifications)
// =============================================
function createUIStore() {
    const { subscribe, set, update } = writable({
        sidebarCollapsed: false,
        activeModal: null, // 'createProject', 'createCategory', 'import', 'userManagement'
        modalData: null,
        notification: null
    });

    return {
        subscribe,
        toggleSidebar: () => {
            update(state => ({ ...state, sidebarCollapsed: !state.sidebarCollapsed }));
        },
        openModal: (modalName, data = null) => {
            update(state => ({ ...state, activeModal: modalName, modalData: data }));
        },
        closeModal: () => {
            update(state => ({ ...state, activeModal: null, modalData: null }));
        },
        showNotification: (message, type = 'info') => {
            update(state => ({ ...state, notification: { message, type } }));
            // Auto-hide after 3 seconds
            setTimeout(() => {
                update(state => ({ ...state, notification: null }));
            }, 3000);
        }
    };
}

export const uiStore = createUIStore();
